@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> p0) {
  final groups = <int, int>{};

  for (final value in p0) {
    final key = value >> 16;
    groups[key] = (groups[key] ?? 0) + 1;
  }

  var result = 0;
  for (final count in groups.values) {
    if (count > 1) {
      result += count;
    }
  }

  return result;
}

