String fn0(List<int> p0) {
  final buffer = StringBuffer();
  String? current;
  var count = 0;

  for (final r in p0) {
    final String letter;
    if (r >= -50) {
      letter = 'E';
    } else if (r >= -60) {
      letter = 'G';
    } else if (r >= -70) {
      letter = 'F';
    } else if (r >= -80) {
      letter = 'P';
    } else {
      letter = 'D';
    }

    if (letter == current) {
      count++;
    } else {
      if (current != null) {
        buffer.write(current);
        buffer.write(count);
      }
      current = letter;
      count = 1;
    }
  }

  if (current != null) {
    buffer.write(current);
    buffer.write(count);
  }

  return buffer.toString();
}

int fn0(List<List<String>> p0) {
  const Set<String> targets = {'.', '-'};
  int total = 0;
  for (int i = 0; i < p0.length; i++) {
    final List<String> row = p0[i];
    for (int j = 0; j < row.length; j++) {
      if (targets.contains(row[j])) {
        total += i + j + 2;
      }
    }
  }
  return total;
