void fn0() {
  const int V = 5;
  final List<List<int>> graph = <List<int>>[
    <int>[0, 2, 0, 6, 0],
    <int>[2, 0, 3, 8, 5],
    <int>[0, 3, 0, 0, 7],
    <int>[6, 8, 0, 0, 9],
    <int>[0, 5, 7, 9, 0],
  ];

  final List<int> parent = List<int>.filled(V, -1);
  final List<int> key = List<int>.filled(V, 1 << 30);
  final List<bool> mstSet = List<bool>.filled(V, false);

  key[0] = 0;

  for (int count = 0; count < V - 1; count++) {
    int minKey = 1 << 30;
    int minIndex = -1;
    for (int v = 0; v < V; v++) {
      if (!mstSet[v] && key[v] < minKey) {
        minKey = key[v];
        minIndex = v;
      }
    }

    mstSet[minIndex] = true;

    for (int v = 0; v < V; v++) {
      if (graph[minIndex][v] != 0 &&
          !mstSet[v] &&
          graph[minIndex][v] < key[v]) {
        parent[v] = minIndex;
        key[v] = graph[minIndex][v];
      }
    }
  }

  print('Edge \tWeight');
  int totalWeight = 0;
  for (int i = 1; i < V; i++) {
    print('${parent[i]} - $i \t${graph[i][parent[i]]}');
    totalWeight += graph[i][parent[i]];
  }
  print('Total weight of MST: $totalWeight');
}

Map<String, int> fn0(List<int> p0) {
  final Map<String, int> counts = {};
  for (int h = 0; h < 24; h++) {
    counts[h.toString().padLeft(2, '0')] = 0;
  }
  for (final int minutes in p0) {
    final int hour = minutes ~/ 60;
    final String key = hour.toString().padLeft(2, '0');
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

Map<String, int> fn0(int p0) {
  int even = 0;
  int odd = 0;

  for (int byteIndex = 0; byteIndex < 8; byteIndex++) {
    final int byte = (p0 >> (byteIndex * 8)) & 0xff;
    int bits = 0;

    for (int bit = 0; bit < 8; bit++) {
      if ((byte & (1 << bit)) != 0) {
        bits++;
      }
    }

    if ((byteIndex & 1) == 0) {
      even += bits;
    } else {
      odd += bits;
    }
  }

  return {'even': even, 'odd': odd};
}

void fn0() {
  final points = <List<double>>[
    [3.0, 6.0],
    [17.0, 15.0],
    [13.0, 15.0],
    [6.0, 12.0],
    [9.0, 1.0],
    [2.0, 7.0],
    [10.0, 19.0],
  ];

  final root = _buildKdTree(List<List<double>>.from(points), 0);
  print('Constructed k-d tree:');
  _printInOrder(root);
}

class _KdNode {
  final List<double> point;
  final int depth;
  _KdNode? left;
  _KdNode? right;
  _KdNode(this.point, this.depth);
}

_KdNode? _buildKdTree(List<List<double>> points, int depth) {
  if (points.isEmpty) return null;
  final axis = depth % 2;
  points.sort((a, b) => a[axis].compareTo(b[axis]));
  final mid = points.length ~/ 2;
  final node = _KdNode(points[mid], depth);
  node.left = _buildKdTree(points.sublist(0, mid), depth + 1);
  node.right = _buildKdTree(points.sublist(mid + 1), depth + 1);
  return node;
}

void _printInOrder(_KdNode? node) {
  if (node == null) return;
  _printInOrder(node.left);
  print('Depth ${node.depth}: ${node.point}');
  _printInOrder(node.right);
}

String fn0(Map<String, List<int>> p0) {
  if (p0.isEmpty) return "NO CANDIDATES";
  final totals = <String, int>{};
  var total = 0;
  for (final entry in p0.entries) {
    var sum = 0;
    for (final v in entry.value) {
      sum += v;
    }
    totals[entry.key] = sum;
    total += sum;
  }
  if (total == 0) return "NO VOTES";
  final candidates = totals.keys.toList();
  candidates.sort((a, b) {
    final cmp = totals[b]!.compareTo(totals[a]!);
    return cmp != 0 ? cmp : a.compareTo(b);
  });
  if (totals[candidates[0]]! * 2 > total) {
    return "ELECTED: ${candidates[0]}";
  }
  return "RUNOFF: ${candidates[0]} vs ${candidates[1]}";
}

int fn0(List<int> p0) {
  var total = 0;
  var followsSix = false;

  for (final value in p0) {
    total += followsSix ? value * 2 : value;
    followsSix = value == 6;
  }

  return total;
}

List<int> fn0(List<List<int>> p0) {
  var even = 0;
  var odd = 0;
  for (final e in p0) {
    if (e.length < 3) continue;
    final x = e[0];
    final y = e[1];
    final v = e[2];
    if (((x * x + y * y) & 1) == 0) {
      even += v;
    } else {
      odd += v;
    }
  }
  return <int>[even, odd];
}
